-- 2266 🏋️ Exercises from the book "coaching-positional-play-expansive-football-attacking-tactics-practices" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'coaching-positional-play-expansive-football-attacking-tactics-practices');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Pairs 2v2 aerial control and shooting game', 'one_v_one', 'opposed', 'in_possession', 70, 71, NULL, NULL, 'Long aerial passing, control, shooting and 2v2 teamwork (overlaps, one-twos, covering, swapping positions).', 'Two goals with keepers in an area about twice a penalty box; four pairs, one pair attacking and one defending inside, the other two pairs waiting on the end lines with balls.', 'Play a normal 2v2; the pair that scores stays on. After scoring they push up towards the far goal and an outside player from a rival pair plays a high ball to them, one partner sets it with a controlled first-time pass to the other who attacks at once. After phase two the inside pairs swap with the outside pairs.', 'First pair to score stays in; the set-up pass after the long ball is one touch.', NULL, 'The receiver of the long pass gets in line with and well positioned for the passer so the set can be controlled easily.', '4 pairs (2v2 plus 2 waiting pairs) + 2 GKs', 8, 10, 'double the size of the penalty box', NULL, NULL, NULL, true, true, true, NULL, 10),
  ('4v4 plus neutral with staggered defender entry', 'small_sided_game', 'overload', 'in_possession', 72, 72, NULL, NULL, 'Positional play, teamwork and communication in a competitive 4v4 game.', 'Same area as the 2v2 game (twice a penalty box) with two goals; 4 attackers plus a yellow neutral inside, one defender inside and his 3 teammates waiting outside.', 'Start 4v1 plus neutral. Every 10 seconds another defender runs on until it is 5v4. If the defending team wins the ball they counter and try to score.', 'Neutral plays with the team in possession and cannot score.', 'Instead of timed entries, waiting players must complete 30 sit-ups before joining, so they work fast to help their teammates.', NULL, '4v4 + 1 neutral', 9, 9, 'double the size of the penalty box', NULL, NULL, NULL, true, false, true, NULL, 20),
  ('4v2 rondo, shared blame for losses', 'rondo', 'overload', 'in_possession', 73, 73, NULL, NULL, 'Positional play, teamwork and communication while keeping the ball.', '10 x 10 yard square, 4 players on the outside and 2 defenders in the middle.', 'The four outside players keep the ball with good movement and talk; the two middle players work as a pair to shut passing lanes and press the ball to win it.', 'Outside players limited to 1 or 2 touches.', NULL, 'Do not automatically send in the player who lost it; judge who was really at fault (bad pass, teammate badly placed) before deciding who goes in.', '4v2', 6, 6, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 30),
  ('Three pairs keep-ball with escape pass', 'rondo', 'overload', 'to_attack', 74, 74, NULL, NULL, 'Positional play, teamwork and communication; quick support after a regain and immediate counter-press after a loss.', 'Square area with two pairs (four players) on the outside and one pair defending in the middle.', '4v2 in pairs. When a middle player wins the ball he tries to find his partner, while the partner of the player who lost it closes him down hard to block that pass. If the regain pass reaches the partner, the middle pair can pass out to the other outside pair, and the pair that lost it swaps into the middle.', NULL, 'Change area size, time and numbers, e.g. 3v3 or 6v3 instead of 2v2 or 4v2, keeping to the game model principles.', 'The ball-winner''s partner must move quickly into a good position to receive away from pressure.', '3 pairs (4v2)', 6, 6, NULL, NULL, NULL, NULL, false, false, false, NULL, 40),
  ('Race to loose ball 2v2 to goal', 'one_v_one', 'opposed', 'in_possession', 77, 77, NULL, NULL, 'Competitiveness and desire to win, plus link play and cooperation in attack and defence.', 'One goal with a keeper; two pairs start side by side on the far line matched to their positions (e.g. 2 centre backs v 2 forwards), a ball placed in the middle; other pairs wait on the side.', 'On the coach''s signal both pairs sprint for the ball; the pair that gets there first attacks the goal together while the other pair defends.', NULL, NULL, 'Attackers use one-twos, vertical passes and overlaps; defenders swap positions, block passes and cover each other.', '2v2 + GK, pairs rotating', 5, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 50),
  ('Two-lane dribble and pass relay', 'warm_up', 'unopposed', NULL, 119, 119, 'Continuous Dribbling/Passing Warm Up', NULL, 'Activate players with dribbling, movement and passing in a continuous relay.', 'Two coned lanes side by side, each with a queue of players at both ends.', 'Lane 1: front player dribbles across, passes to the player opposite and joins that queue. Lane 2: player passes to the opposite queue and runs after the ball to the far end; the receiver steps in, passes on and follows.', NULL, NULL, 'Raise the tempo so nobody stands still.', '2 groups of about 6', 8, 16, NULL, NULL, NULL, NULL, false, false, false, NULL, 60),
  ('Positional 4v1 / 4v2 keep-ball', 'rondo', 'opposed', 'in_possession', 120, 120, 'Positional 4 v 1 / 4 v 2 Possession Game', NULL, 'Create passing angles to keep the ball; defenders win it and play it on quickly.', '8 x 12 yard box with 4 attackers in triangle/diamond shapes round it and 1 or 2 defenders inside.', 'Attackers keep the ball. When a middle player wins it he plays as if starting a counter, passing quickly to the outside; the player who lost it presses the new ball carrier. If the outlet pass succeeds the loser swaps in for the winner.', 'Roles swap on a successful turnover and outlet pass.', 'Play 4v1 or step up to 4v2.', 'Players take up the positions they would hold in a real game.', '4v1 or 4v2', 5, 6, '8 x 12 yards', 11.0, 7.3, NULL, false, false, false, NULL, 70),
  ('Two-line positional pass and move', 'passing_unopposed', 'unopposed', 'in_possession', 121, 121, 'Technical Passing and Receiving in a Positional Practice', NULL, 'Practise receiving and passing in every position of the team shape.', 'Half pitch; a back line of 5 (2 full backs, 2 centre backs, defensive midfielder) and a front line of 5 (2 wingers, 2 attacking midfielders, striker) on blue cones.', 'Two balls go round at once; each player passes along his line in a set order and follows the pass to the next position, so everyone cycles through all roles.', NULL, 'Add more balls to raise speed and rhythm.', 'Learn each teammate''s role and how to receive and pass along the chain; feed a new ball straight away after a bad pass.', '10 (two lines of 5)', 10, 12, 'half pitch', NULL, NULL, NULL, false, false, false, NULL, 80),
  ('Six-zone 9v9 build-up game', 'small_sided_game', 'opposed', 'in_possession', 123, 123, 'Building Up Play in a 6 Zone 9 v 9 Small Sided Game', NULL, 'Build possession through the thirds with smart movement and sharp acceleration.', 'Half a full pitch split into 6 zones (3 per half), goal at each end; 8 outfield players plus a goalkeeper per side.', 'The team in possession must play through all 3 zones of its own half, then all 3 zones of the opponent''s half, before it may shoot. If the other side wins the ball it must pass into another zone at once, after which it becomes a normal attack v defence game.', 'No corner-to-corner passes inside a square; play through the middle.', NULL, 'Get the full backs involved in attacks.', '9v9 incl. GKs', 18, 18, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 90),
  ('7v5 attack through halfway gates', 'phase_of_play', 'overload', 'in_possession', 124, 124, 'Attacking from Back to Front in an 8 v 6 Game with Cone Gates', NULL, 'Attack from back to front through central gates, using full backs to make 2v1s wide.', 'Full pitch with 3 cone gates on the halfway line and a goalkeeper in each goal; 7 red attackers (2 full backs, 2 attacking mids, 2 wingers, striker) v 5 white defenders (back 4 plus a defensive mid).', 'Reds must pass through one of the halfway gates before they may score. Whites shift across to block; if they win it they too must play through a gate before attacking the other goal.', 'No direct winger-to-winger switch; ball must go through central players.', NULL, 'Full backs create 2v1s wide; the striker stays high as an outlet and for depth; the defensive mid holds the line with his back four.', '8v6 incl. GKs (7v5 outfield)', 14, 14, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Three-team 5v5 plus 4 wide neutrals', 'small_sided_game', 'overload', 'in_possession', 125, 125, 'Positional Play in a Dynamic 3 Team 5 v 5 (+4) Small Sided Game', NULL, 'Positional play to goal using wide neutrals, with pressing to win the ball back.', 'Box round the penalty area with goals and keepers at each end; two teams of 4 (defensive mid, 2 attacking mids, striker) inside, third team of 4 (2 wingers, 2 full backs) on the outside as neutrals.', 'Normal game, but the ball must reach a neutral before a goal counts. The first team to concede 2 goals swaps out to become the neutrals.', 'Neutral cannot pass to neutral; goal direct from a neutral''s cross counts double; a player who wins the ball may score without using a neutral.', NULL, 'Hold outside neutrals to 1 touch; rotate positions often so all learn different roles.', '3 teams of 4 plus 2 GKs', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 110),
  ('Passing diamond with one-two', 'passing_unopposed', 'unopposed', 'in_possession', 127, 127, 'Technical Passing Diamond with One-Two Combination', NULL, 'Technical passing that uses width, depth and a one-two.', '20 x 20 yard area, groups of 6: 4 on diamond positions inside and 2 waiting outside.', 'Player 1 plays wide to 2, who comes off his cone and passes inside to 3; 3 sets to 4, who returns it first time (one-two). 3 then plays into 4''s run across, and 4 plays back to the start. Each player follows to the next spot.', NULL, 'Reverse the direction so both feet are used.', 'Make space before coming to the ball; open body shape.', 'groups of 6', 6, 6, '20 x 20 yards', 18.3, 18.3, NULL, false, false, false, NULL, 120),
  ('Build-up to wide cross and finish', 'combination', 'unopposed', 'in_possession', 128, 128, 'Build Up Play, Quick Attacking Runs, Combination Play and Finishing', NULL, 'Positioning and combination play over a full pitch ending in a cross and finish.', 'Full pitch; white back four at one end, red defensive mid, 2 attacking mids and striker in the middle, keepers in both goals.', 'Centre back 5 plays across to 4, who finds the 6 while the full backs bomb on. 6 combines with the 8/10, who feed the 9; the 9 plays wide to a full back who crosses for the striker and other full back arriving in the box. Restart the other way with a fresh white back four.', NULL, 'Add 2 defenders on the 3 reds for a 3v2 and one on the striker for 3v1; with aggressive defending it becomes an IPTETA drill. Can bridge warm-up and main session.', NULL, '4 white defenders, 4 reds, 2 GKs (per end)', 10, 14, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Dribble at mannequin, diagonal release', 'technical', 'unopposed', 'in_possession', 129, 129, 'Dribbling Forwards to Draw in a Marker and Create Space for a Teammate', NULL, 'Carry the ball forward to pull a marker away and free a teammate.', 'Two groups working at once across the pitch, each with mannequins (or cones) standing in as opponents.', 'First two players set off together with a ball each, dribble at the mannequin and, just before reaching it, play a diagonal pass to a teammate; the passer then moves to the spot ahead. The next pair repeats.', NULL, NULL, 'Mimics a centre back driving forward to draw a marker; everyone does it as the action applies all over the pitch.', '2 groups', 8, 16, NULL, NULL, NULL, NULL, false, false, false, NULL, 140),
  ('Pass along back and midfield lines', 'passing_unopposed', 'unopposed', 'in_possession', 130, 130, 'Passing Across the Defensive and Midfield Lines', NULL, 'Circulate the ball along the defensive and midfield lines.', 'Half pitch; back line of 2 full backs, 2 centre backs and keeper facing a midfield line of 2 wingers, 2 attacking mids and striker. Two balls start with a full back and a winger.', 'Pass and move to the next spot. Back line: full back to full back via centre backs and keeper, then into the winger ahead. Midfield: the winger acts as if shut off, plays inside to the attacking mid, on to the 9, across to the other winger, who plays back to the full back to restart.', '1-2 touches.', NULL, 'Quick 1-2 touch play; learn positioning, body shape and passing technique in each spot along the line.', '11 (two lines)', 11, 13, 'half pitch', NULL, NULL, NULL, false, true, false, NULL, 150),
  ('Two-line inside-out switch pattern', 'passing_unopposed', 'unopposed', 'in_possession', 131, 131, 'Quick Positional Combination Play to Switch the Play', NULL, 'Movement and switching play with quick combinations.', 'Half pitch; two separate lines facing each other: back 4 plus defensive mid near the box, and 2 wingers (slightly moved from previous drill), 2 attacking mids and striker.', 'Each line starts wide, moves the ball inside and then across to the far side; players follow their pass to the next spot, and after the 5th pass the wide player runs back to the start.', NULL, NULL, NULL, '10 (two lines of 5)', 10, 12, 'half pitch', NULL, NULL, NULL, false, false, false, NULL, 160),
  ('Passing square, short and long support', 'passing_unopposed', 'unopposed', 'in_possession', 132, 132, 'Positional Passing Square with Short and Long Support Play', NULL, 'Short and long passing, combinations and timing of support runs.', '30 x 30 yard area, 2 groups of 6 in set positions; balls start with an attacking mid and a centre back in opposite corners.', 'Attacking sequence: 8 to 9, 9 to 10, 10 plays long to the far centre back (like a deep pass to a breaking winger or overlapping full back). Defensive sequence: centre back to 6, 6 to the other centre back, who finishes with a pass to the 8 of the other group.', NULL, NULL, 'Check away before showing so you can play one touch; keep ball and players moving.', '12 (2 groups of 6)', 12, 12, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 170),
  ('Front-five diagonal rotation pattern', 'passing_unopposed', 'unopposed', 'in_possession', 133, 133, 'Quick Combination Play with Positional Inter-Changing of Diagonal Movements', NULL, 'Attacking combinations and movement in the opposition half.', 'Half pitch; 2 attacking mids, 2 wingers, a striker and one extra player on start positions.', '10 plays out to his winger (7), who plays across to the other attacking mid (8), who finds the near winger (11); 11 feeds the 9 who plays back to the start where the extra player waits. Everyone follows his pass.', NULL, NULL, 'Check away from the cone and aim for one touch; protect the ball with body shape as if a defender were closing.', '6', 6, 8, 'half pitch', NULL, NULL, NULL, false, false, false, NULL, 180),
  ('Switch the attack into a cross', 'combination', 'unopposed', 'in_possession', 134, 134, 'Switching the Point of Attack with Player Movement in the Final Third', NULL, 'Switch the point of attack in the final third and finish from a cross.', 'Final third with goal; full backs, wingers, attacking mids and striker. Start on the side where the full back is assumed blocked (numbers even on that flank).', 'Left back plays to his winger, into the 10, who links with the 8 directly or via the 9. 8 finds the far winger, who releases the right back wide; the full back crosses as players attack the box. Repeat from the other side.', NULL, NULL, NULL, '8 attackers', 8, 9, 'final third', NULL, NULL, NULL, true, false, true, NULL, 190),
  ('Winger dribble, one-two, finish', 'finishing', 'unopposed', 'in_possession', 135, 135, 'Technical / Tactical Actions on the Wing: Dribble, Support Play & Finishing', NULL, 'Wingers practise dribbling, quick combinations and finishing, with emphasis on the weaker foot.', 'Half pitch with goal and keeper; coaching poles as opposing full backs and defenders; wingers with balls on both flanks, striker/attacking mid in the centre.', 'Winger dribbles at the first pole, cuts inside and plays a one-two with the striker (or attacking mid) who comes off his cone; winger runs in behind, takes the return in the box and shoots. Run both sides at once.', NULL, 'Swap mannequins for passive defenders.', NULL, '2 wingers, 2 support players, GK', 5, 8, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 200),
  ('Striker goes dark, turns and shoots', 'finishing', 'unopposed', 'in_possession', 136, 136, 'Technical / Tactical Actions for Attacking Through the Centre', NULL, 'Striker movement off a marker, turning on the half-turn and finishing.', 'Centre of the pitch toward goal with keeper; two mannequins (or cones) as opponents; midfielders with balls at the centre circle.', '8 dribbles at the first mannequin and passes to the striker, who has moved to ''go dark'' out of his marker''s sight. The striker receives on the half-turn, dribbles past the second mannequin and shoots.', NULL, NULL, 'Striker drops to find space, checks over his shoulder and receives on the back foot to turn.', 'midfielders, striker, GK', 3, 6, NULL, NULL, NULL, NULL, true, true, true, NULL, 210),
  ('Centre backs build via 6, 3v2 to 3v3', 'transition', 'overload', 'in_possession', 138, 138, 'Centre Backs: Building Up Play Through the Defensive Midfielder', NULL, 'Centre backs build out through the defensive mid under pressure, then exploit the overload quickly.', 'Area twice the size of the penalty box with a goal and keeper at each end; 2 red centre backs plus a waiting red 6; 2 white forwards plus a waiting white 8.', 'Red keeper plays to a centre back while 2 white forwards press. Once both centre backs and the keeper have touched it, the red 6 enters for a 3v2 and reds attack to score fast. After 7 seconds the white 8 joins, reds must give the ball to whites, and whites attack the other goal 3v3.', 'Red 6 only enters after CBs and GK have all touched the ball; 7-second limit before the white 8 joins.', NULL, 'Finish inside 7 seconds while the numerical edge lasts.', '3v3 plus 2 GKs', 8, 8, 'double penalty box', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Zonal build-up: back four and holding mid', 'phase_of_play', 'opposed', 'in_possession', 139, 139, NULL, NULL, 'Links the back line with the holding midfielder and the full back with the winger, moving the ball through two zones.', '40 x 55 yd area split into two zones; reds = GK, 2 centre backs, 2 full backs, holding mid; whites = striker, attacking mid, 2 wingers; two of each side per zone; small goals out wide stand in for the wingers, big goal at the far end.', 'Reds build from the keeper; the ball can only go into zone 2 after both centre backs (helped by the 6) have played it; a full back who receives then aims a pass into his small goal as if finding the winger. If whites win it they attack the big goal.', 'Only the red holding midfielder may cross between zones.', NULL, NULL, '6v4', 10, 10, '40 x 55 yards', 50.3, 36.6, NULL, true, true, true, NULL, 230),
  ('Build-out from position squares 6v6', 'phase_of_play', 'opposed', 'in_possession', 140, 140, NULL, NULL, 'Playing out from the back while each player keeps a fixed positional role.', 'Five 2 x 2 yd squares marked for the 4 red defenders and the holding mid; GK in big goal; 5 white attackers in a 4-1 shape press.', 'Reds build up and finish in the large goal. Defenders must take the ball inside their own square, then can step out and play; the 6 must touch the ball before any shot.', 'Whites cannot enter the squares but may tackle once a player leaves his square; the 6 must touch it at least once before a shot.', NULL, 'Open body, receive on the back foot, head up for the next pass; time forward runs when combining with the 6.', '6v6', 11, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 240),
  ('Dribble forward for overloads in 3 zones', 'phase_of_play', 'opposed', 'in_possession', 141, 141, NULL, NULL, 'Dribbling the ball forward (full backs, centre backs, wingers) to create a numbers-up situation higher up.', 'Same-size area as the previous practice split into 3 equal zones, 7v7, two players from each team per zone, one big goal with GK.', 'The ball moves zone to zone only by a player dribbling across the line, making 3v2 in the next zone; the team works from zone 1 to zone 3 and uses the 3v2 to score.', 'A player can only leave his zone by dribbling over the line.', NULL, 'Centre backs check away from markers to make space; open body before receiving; be positive dribbling into space.', '7v7', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 250),
  ('Four-line passing into transition attack', 'transition', 'overload', 'to_attack', 142, 143, NULL, NULL, 'Passing technique and body shape, then switching on command into attack versus defence.', 'Full pitch split into 4 equal zones, a line of 5 in each; zones 1 and 4 hold back four + holding mid (red and blue), zones 2 and 3 hold the other midfielders + striker (yellow and white); each line has a ball; a pink neutral joins the attacking lines; GKs in both goals.', 'Phase 1: every line passes among itself, focusing on quality and body shape. Phase 2 (coach''s whistle): defenders kick their ball out and close up; the middle lines attack them with the neutral, 6v5 plus GK - white attack the reds, yellow attack the blues.', NULL, NULL, 'Progress the ball wide to stretch the defence and find gaps; react fast to the whistle and take up defending or attacking roles.', '20 + 2 neutrals + 2 GKs', 24, 24, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Wide combination and cross 7v2', 'combination', 'opposed', 'in_possession', 144, 144, NULL, NULL, 'Rehearse the attacking combinations and runs of the game model against two live defenders.', 'Half pitch; reds = 2 attacking mids, 2 wingers, 2 full backs and a striker; 2 white centre backs defend the goal with a GK.', 'Full back plays winger, winger to 10, 10 finds the 8 directly or through the 9; the 8 plays the far winger, who sets the full back to cross while others make runs into the box away from the two defenders.', NULL, 'Run from both sides.', 'Teach the correct runs; timing of runs into the box and moving away from the defenders.', '7v2 + GK', 10, 10, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 270),
  ('Full backs exploit overload 8v6', 'phase_of_play', 'overload', 'in_possession', 145, 145, NULL, NULL, 'Use the full backs to exploit a numerical advantage in attack.', 'Normal small-sided area; reds (GK, 2 full backs, 2 attacking mids, 2 wingers, striker) start with the ball against whites (GK, 4 defenders, holding mid).', 'Reds use their extra players to score; whites defend and on winning the ball counter to the goal at the other end.', NULL, NULL, 'Full backs overlap or underlap to make space or get in behind; many players time runs into the box for crosses.', '8v6', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Central keep-ball then switch and cross', 'finishing', 'overload', 'in_possession', 146, 146, NULL, NULL, 'Keep the ball in a tight central space, then hit a diagonal forward pass for a cross and finish.', 'Square in the middle of a full pitch with two teams of 3 inside; outside: 5 neutrals (2 central mids, 2 wingers, striker); GK in goal.', 'After 4 passes inside the square (using the neutral mids) the team sends a long low ball to a winger; the striker, central mids and far winger attack the cross to score.', 'Neutral central mids support but cannot enter the square and are one-touch.', NULL, NULL, '3v3 + 5 neutrals + GK', 12, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Eight-goal 10v10 width game', 'conditioned_game', 'opposed', 'in_possession', 147, 147, NULL, NULL, 'Use the full width and depth of the area to build up and break a defence down.', 'Area between the two penalty boxes; each team attacks 4 goals (2 wide, 2 at the box edge) and defends the other 4.', '10v10: both teams build up, create space and try to score in any of their 4 goals.', 'Wide goals score 1 point, goals at the edge of the box score 2.', NULL, 'If play gets crowded on one side, switch it; defenders must think about positioning to cover all 4 goals.', '10v10', 20, 20, 'between the penalty boxes', NULL, NULL, NULL, true, false, true, NULL, 300),
  ('Switch through side zones 7v7', 'small_sided_game', 'opposed', 'in_possession', 148, 148, NULL, NULL, 'Move the ball from side to side to play expansive football.', 'Half pitch: central area the width of the penalty box plus two side zones; the attacking team''s full backs sit one in each side zone; GK in goal.', 'Normal game, but the team in possession must play the ball through the central zone, a side zone and the penalty area before scoring; if defenders win it they must do the same.', 'Defenders cannot enter the side zones and may only enter the box once an attacker has gone in.', NULL, 'Outnumbered centrally, so move the ball quickly wide; timing the run for the cross is key.', '7v7', 14, 14, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Flank overloads with side zones 9v8', 'phase_of_play', 'overload', 'in_possession', 149, 150, NULL, NULL, 'Switch play to create 2v1 or 3v2 on the flanks.', 'Half pitch in 5 zones; reds GK, 2 full backs, holding mid, 2 attacking mids, 2 wingers, striker v whites GK, 4 defenders, holding mid, 2 attacking mids; defender-free squares by the byline.', 'Reds play through all 3 channels and make a 2v1 or 3v2 wide, enter the byline square and cross high or low. If whites win it they attack positionally through the 3 channels.', 'Ball-side wide zone: 2-3 attackers; far wide zone: 1-2. Defenders allowed 1 in a zone holding 2 attackers, 2 if 3; none in the far side zone; no defender in the box until an attacker enters.', NULL, 'Wide receiver dribbles inside to free the overlap; far full back and winger never in line.', '9v8', 17, 17, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Full backs in wide zones 8v8+1', 'small_sided_game', 'overload', 'in_possession', 151, 151, NULL, NULL, 'Connect defence, midfield and attack using the full backs for width.', '30 x 70 yd area in 3 zones (end zones 30 x 20, middle 30 x 30); zone 1: GK, 2 red centre backs, 2 white strikers; full backs outside the area; neutral plays with the ball.', 'A defender dribbles out of zone 1 with neutral support; in zone 2 he passes to his full back outside, one opponent may go out to challenge, a midfielder comes closer for a pass or one-two. Teams swap roles on turnover.', 'Both full backs must touch the ball before a goal; only 2 defenders and 2 attackers may enter zone 3.', NULL, NULL, '8v8+1', 17, 19, '30 x 70 yards', 64.0, 27.4, NULL, true, true, true, NULL, 330),
  ('Back-line switch into counter', 'transition', 'overload', 'to_attack', 152, 153, NULL, NULL, 'Full back and winger links, expansive play and the transition to attack.', 'Slightly more than half a pitch; whites 8 players, reds 7, two pink neutral wingers; GKs.', 'White defence circulates against passive red pressing; when a full back finds a neutral, the neutral plays to a red attacker and reds attack with neutrals joining wide, 8v7 outfield. If whites regain it they attack the opposite goal with the neutrals.', 'Reds press passively until the neutral passes to them.', NULL, NULL, '8v7 + 2 neutrals', 17, 17, 'just over half a pitch', NULL, NULL, NULL, true, true, true, NULL, 340),
  ('Two mids and striker 3v2', 'one_v_one', 'overload', 'in_possession', 154, 154, NULL, NULL, 'Interplay between the two attacking midfielders and the striker.', '20 x 40 yd area with a goal and GK at each end; groups of 2 attacking mids and a striker waiting at each end.', 'One attacking mid plays into the striker, who sets the other mid, and the three attack 2 defenders quickly. After the attack, the two mids stay as the next defenders and the old defenders take a ball to go the other way with the opposite 9.', NULL, NULL, NULL, '3v2 rotating', 10, NULL, '20 x 40 yards', 36.6, 18.3, NULL, true, true, true, NULL, 350),
  ('Mids and striker combine 3v3 in two zones', 'small_sided_game', 'opposed', 'in_possession', 155, 155, NULL, NULL, 'Interplay between the two attacking mids and the striker.', 'Area twice the size of the penalty box, two equal zones; zone 1: red GK (acts as holding mid) and 2 attacking mids v a white holding mid; zone 2: red striker v 2 white centre backs and GK.', 'Reds feed the striker; the mid who passed to him joins to make 2v2 and they combine to score. After a goal, save or ball out, roles reverse and whites attack the other way.', 'Both mids and the GK must touch the ball before the pass to the striker.', NULL, 'High tempo, use the full width.', '4v4', 8, 8, 'double penalty box', NULL, NULL, NULL, true, true, true, NULL, 360),
  ('Three-zone build-up 7v7 to the striker', 'small_sided_game', 'opposed', 'in_possession', 156, 156, NULL, NULL, 'Midfield-to-striker interplay in a small-sided game.', '30 x 60 yd area in three equal zones; each team GK, 2 centre backs, holding mid, 2 attacking mids, striker.', 'GK starts; teams build through the 3 zones; once a mid passes into the striker, he or another mid may join the striker''s zone for 2v2 and a finish.', 'Centre backs, 6s and 9s stay in their zones; only the 8s and 10s may cross zones.', 'Progression of the 3v3 functional practice.', NULL, '7v7', 14, 14, '30 x 60 yards', 54.8, 27.4, NULL, true, true, true, NULL, 370),
  ('Zonal 7v7+3 striker support game', 'small_sided_game', 'overload', 'in_possession', 157, 157, NULL, NULL, 'Support movement so the striker can receive out of his marker''s sight.', 'Three central zones plus two wide lanes for 2 neutral wide players; a third neutral in zone 2; both teams in 2-1-3 (2 defenders, holding mid, 3 forwards) with GKs.', 'Team in possession has defenders in zone 1, the 6 in zone 2, forwards in zone 3. A defender may dribble into zone 2, then the striker drops into zone 2 to support. On regaining, play quickly to the striker with the zone 2 neutral, and two players join the end zone for 3v2.', 'Before scoring, a neutral and the striker (in zone 2) must touch the ball; defending team moves freely.', NULL, NULL, '7v7+3', 17, 17, NULL, NULL, NULL, NULL, true, true, true, NULL, 380),
  ('Hexagon 8v3 into 10v8 keep-ball', 'transition', 'overload', 'to_attack', 160, 161, NULL, NULL, 'Keep possession through all four phases, reacting to regains and losses.', 'Hexagon template: GK and big goal at one end, poles at the other; red back four, wingers and striker on the hexagon in match positions; red 6, 8 and 10 inside the centre circle; 8 whites (the less-used players) on the circle edge.', '8 whites keep it round the circle v the 3 reds inside. If reds win it they find teammates on the hexagon and it becomes 10v8 in the whole hexagon (3 reds inside, 7 outside). If whites win it back they return to 8v3 round the circle.', 'Whites cannot enter the circle in the 8v3.', NULL, 'Relies on white mobility; after a bad pass that is not lost, react and keep the ball.', '8v3 then 10v8 + GK', 19, 19, NULL, NULL, NULL, NULL, false, true, false, NULL, 390),
  ('Hexagon keep-ball with counter to goal', 'transition', 'overload', 'to_attack', 162, 162, NULL, NULL, 'Possession, collective pressing, tackling, counter-attacks and quick team reactions.', 'Same hexagon template: GK and big goal one end, pole gates on the far side.', 'Starts as 8v3 in the circle, then 10v8 if reds win it. If whites regain from reds they counter at the big goal; reds get into shape to defend, and on winning it attack the other way, scoring by dribbling or passing through the poles at the sides.', NULL, 'Progression of the 8v3 / 10v8 game.', NULL, '8v3 then 10v8 + GK', 19, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 400),
  ('4v4+3 positional keep-ball: width', 'possession', 'overload', 'in_possession', 165, 165, NULL, NULL, 'Keep possession in set positional roles with a focus on width.', '30 x 40 yd area; teams of 2 centre backs and 2 attacking mids; neutrals = 2 full backs wide and the 6 in the middle.', 'Team on the ball keeps it with the neutrals, everyone holding their positions in attack and defence.', 'Unlimited touches; neutrals can be tackled and stay in their coned areas.', NULL, 'Attackers make the pitch big, defenders make it small; mix flank and central overloads but favour width.', '4v4+3', 11, 11, '30 x 40 yards', 36.6, 27.4, NULL, false, false, false, NULL, 410),
  ('4v4+3 positional keep-ball: through the middle', 'possession', 'overload', 'in_possession', 166, 166, NULL, NULL, 'Keep possession in set roles, now playing through the centre from back to front.', '30 x 40 yd area; teams of 2 centre backs and 2 attacking mids; neutrals = GK and striker at the ends, the 6 in the middle.', 'Team on the ball keeps it with the neutrals, keeping positions in attack and defence.', 'GK may not use his hands.', 'Variation of the width version.', 'Make the pitch big in possession, small out of it; overload centrally and use the 6.', '4v4+3', 11, 11, '30 x 40 yards', 36.6, 27.4, NULL, false, true, false, NULL, 420),
  ('7v7+3 positional keep-ball wide and inside', 'possession', 'overload', 'in_possession', 167, 167, NULL, NULL, 'Keep the ball by creating overloads centrally or wide, mixing inside and outside play.', '40 x 60 yd area; teams of 2 centre backs, 2 full backs, 2 attacking mids and a striker; neutrals = 2 wingers and the 6.', 'Team on the ball keeps it with the neutrals.', 'Unlimited touches; neutrals stay in their areas.', NULL, 'Hold positions in both phases; use neutrals inside and wide to exploit the 10v7.', '7v7+3', 17, 17, '40 x 60 yards', 54.8, 36.6, NULL, false, false, false, NULL, 430),
  ('6v6+4 positional keep-ball back to front', 'possession', 'overload', 'in_possession', 168, 168, NULL, NULL, 'Constant depth, playing forward, in both attack and defence.', '40 x 60 yd area; teams of 2 full backs, 2 attacking mids and 2 wingers; neutrals = 2 centre backs, the 6 and the striker.', 'Team on the ball keeps it with the neutrals, all holding positions in attack and defence.', 'Unlimited touches; neutrals stay in their areas.', NULL, NULL, '6v6+4', 16, 16, '40 x 60 yards', 54.8, 36.6, NULL, false, false, false, NULL, 440),
  ('4v4+3 through centre to striker finish', 'small_sided_game', 'overload', 'in_possession', 171, 171, NULL, NULL, 'Play forward through the middle and link with the striker to score.', '30 x 80 yd area with 30 x 40 central zone and end zones; teams of 2 centre backs and 2 central mids in the middle zone; neutrals = GK and striker at the ends, 6 in the middle; goals at the ends.', 'After at least 5 passes involving a neutral, the team can feed the neutral striker, who turns into the end zone and shoots. Roles reverse after a goal, ball out or turnover.', 'Minimum 5 passes with neutral involvement before playing to the striker.', NULL, NULL, '4v4+3', 11, 11, '30 x 80 yards', 73.2, 27.4, NULL, true, true, true, NULL, 450),
  ('Zonal 6v6+4 attack through centre', 'small_sided_game', 'overload', 'in_possession', 172, 172, NULL, NULL, 'Always play towards goal and connect with the striker to score.', '50 x 70 yd area in three zones; 3v1 in each end zone, 3v3 midfielders in the centre; neutrals help in the end zones; GKs in both goals.', 'The middle three try to connect with the striker in the end zone, who then scores with two neutrals'' support (3v1). On a turnover, attack the other way under the same rules.', 'Players stay in their zones.', NULL, NULL, '6v6+4', 16, 18, '50 x 70 yards', 64.0, 45.7, NULL, true, true, true, NULL, 460),
  ('Zonal 9v9 defence-midfield-attack link', 'conditioned_game', 'overload', 'in_possession', 173, 173, NULL, NULL, 'Connect the lines between zones and finish with the front three.', '55 x 75 yd area; both teams GK, 2 centre backs, 2 attacking mids, holding mid, 2 wingers, striker in a 2-3-3; central coned zone with 3v3.', 'A centre back dribbles into the central zone for 4v3 and the team combines through the middle, then feeds a winger or the striker to use the 3v2 in the attacking zone and score.', 'Play always goes towards goal.', NULL, NULL, '9v9', 18, 18, '55 x 75 yards', 68.6, 50.3, NULL, true, true, true, NULL, 470)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'coaching-positional-play-expansive-football-attacking-tactics-practices') b;
INSERT INTO schema_migrations (filename) VALUES ('2266-exercises-book-coaching-positional-play-expansive-football-attacking-tactic.sql') ON CONFLICT DO NOTHING;
COMMIT;
